SmtLibParseException::~SmtLibParseException() = default;

namespace smt {

namespace {

bool has_sort_kind(SortKind sk, const Term & t)
{
  return t->get_sort()->get_sort_kind() == sk;
}
// Curried form of has_sort_kind(sk, t): returns a predicate on terms.
auto has_sort_kind(SortKind sk)
{
  return [sk](const Term & t) { return has_sort_kind(sk, t); };
}

/** Closes the input file of a parse */
struct CloseFile
{
  void operator()(std::FILE * input) const { std::fclose(input); }
};

/** Closes the argument scopes a failed parse leaves open */
struct CloseScopes
{
  SmtLibReader & reader;
  ~CloseScopes()
  {
    while (reader.current_scope())
    {
      reader.pop_scope();
    }
  }
};
}  // namespace

std::size_t UnorderedScopedSymbolMap::current_scope() const
{
  return symbols_.size() - 1;
}

void UnorderedScopedSymbolMap::add_mapping(const std::string & sym,
                                           const Term & t)
{
  if (!symbols_.back().insert(sym).second)
  {
    throw IncorrectUsageException("Repeated symbol: " + sym);
  }
  symbol_map_[sym].push_back(t);
}

void UnorderedScopedSymbolMap::push_scope() { symbols_.push_back({}); }

void UnorderedScopedSymbolMap::pop_scope()
{
  if (!current_scope())
  {
    throw IncorrectUsageException("Cannot pop the outermost scope");
  }
  for (const auto & sym : symbols_.back())
  {
    auto it = symbol_map_.find(sym);
    it->second.pop_back();
    if (it->second.empty())
    {
      symbol_map_.erase(it);
    }
  }
  symbols_.pop_back();
}

Term UnorderedScopedSymbolMap::get_symbol(const std::string & sym) const
{
  Term res;
  auto it = symbol_map_.find(sym);
  if (it != symbol_map_.end())
  {
    res = it->second.back();
  }
  return res;
}

SmtLibReader::SmtLibReader(SmtSolver & solver, bool strict)
    : solver_(solver), strict_(strict)
{
  // every logic includes the core theory
  add_theory(LogicTheory::CORE);
}

void SmtLibReader::parse(const std::string & f)
{
  file = f;
  std::unique_ptr<std::FILE, CloseFile> input_file;
  if (!file.empty() && file != "-")
  {
    input_file.reset(std::fopen(file.c_str(), "r"));
    if (!input_file)
    {
      int open_errno = errno;
      throw IncorrectUsageException("Cannot open " + file + ": "
                                    + std::strerror(open_errno));
    }
  }

  SmtLibParser::location_type location(&file);
  SmtLibScanner scanner(input_file ? input_file.get() : stdin, location);

  CloseScopes close_scopes{ *this };
  SmtLibParser parser(scanner, *this);
  try
  {
    parser.parse();
  }
  catch (const SmtLibParser::syntax_error & e)
  {
    std::ostringstream message;
    message << e.location << ": " << e.what();
    throw SmtLibParseException(message.str());
  }
  // the reader or the solver refusing something the input asks for
  catch (const IncorrectUsageException & e)
  {
    std::ostringstream message;
    message << location << ": " << e.what();
    throw SmtLibParseException(message.str());
  }
  catch (const InternalSolverException & e)
  {
    std::ostringstream message;
    message << e.what() << " (" << location << ")";
    throw InternalSolverException(message.str());
  }
}

void SmtLibReader::set_logic(const std::string & logic)
{
  solver_->set_logic(logic);
  logic_ = logic;

  if (logic == "ALL")
  {
    for (int theory = 0; theory < static_cast<int>(LogicTheory::NUM_THEORIES);
         ++theory)
    {
      add_theory(static_cast<LogicTheory>(theory));
    }
    return;
  }

  std::string_view rest = logic;
  if (rest.substr(0, 3) == "QF_")
  {
    // parser doesn't distinguish -- let solver complain
    // if using quantifiers in quantifier-free logic
    rest.remove_prefix(3);
  }

  // The arithmetic comes last, as I, R or IR followed by A for arithmetic
  // or DL for difference logic, and QF_AX ends in the X of extensionality.
  // These suffixes declare no symbols.
  if (rest.size() >= 2 && rest.substr(rest.size() - 2) == "DL")
  {
    rest.remove_suffix(2);
  }
  else if (rest.size() >= 2
           && (rest.substr(rest.size() - 2) == "IA"
               || rest.substr(rest.size() - 2) == "RA"
               || rest.substr(rest.size() - 2) == "AX"))
  {
    rest.remove_suffix(1);
  }

  // the abbreviations of the theories, none a prefix of another, with
  // linear (L) and nonlinear (N) arithmetic declaring nothing of their own
  static constexpr std::pair<std::string_view, LogicTheory> abbreviations[] = {
    { "A", LogicTheory::A },    { "BV", LogicTheory::BV },
    { "UF", LogicTheory::UF },  { "S", LogicTheory::S },
    { "I", LogicTheory::IA },   { "R", LogicTheory::RA },
    { "L", LogicTheory::CORE }, { "N", LogicTheory::CORE },
  };
  while (!rest.empty())
  {
    std::size_t len = 0;
    for (const auto & [abbreviation, theory] : abbreviations)
    {
      if (rest.substr(0, abbreviation.size()) == abbreviation)
      {
        add_theory(theory);
        len = abbreviation.size();
        break;
      }
    }
    if (len == 0)
    {
      throw IncorrectUsageException("Failed to interpret logic: " + logic);
    }
    rest.remove_prefix(len);
  }

  // the conversions between the theories that a logic combines
  if (lookup_sortkind(to_string(INT)) == INT
      && lookup_sortkind(to_string(REAL)) == REAL)
  {
    add_theory(LogicTheory::IRA);
  }
  if (lookup_sortkind(to_string(INT)) == INT
      && lookup_sortkind(to_string(BV)) == BV)
  {
    add_theory(LogicTheory::BVIA);
  }
}

void SmtLibReader::add_theory(LogicTheory theory)
{
  std::optional<SortKind> sort;
  std::vector<PrimOp> ops;
  switch (theory)
  {
    case LogicTheory::CORE:
      sort = BOOL;
      ops = {
        And, Or, Xor, Not, Implies, Ite, Equal, Distinct, Forall, Exists
      };
      break;
    case LogicTheory::UF:
      // no sort or operator, so that neither Function nor apply is
      // reserved
      allow_ufs_ = true;
      break;
    case LogicTheory::IA:
      sort = INT;
      // - with one argument is Negate, which apply_primop picks
      ops = { Plus, Minus, Lt, Le, Gt, Ge, Mult, IntDiv, Mod, Divisible, Abs };
      if (!strict_)
      {
        ops.push_back(Pow);
      }
      break;
    case LogicTheory::RA:
      sort = REAL;
      // - with one argument is Negate, which apply_primop picks
      ops = { Plus, Minus, Lt, Le, Gt, Ge, Mult, Div };
      break;
    case LogicTheory::IRA: ops = { To_Real, To_Int, Is_Int }; break;
    case LogicTheory::BV:
      sort = BV;
      ops = { Concat,      Extract,     BVNot,  BVNeg,       BVAnd,
              BVOr,        BVXor,       BVNand, BVNor,       BVXnor,
              BVComp,      BVAdd,       BVSub,  BVMul,       BVUdiv,
              BVSdiv,      BVUrem,      BVSrem, BVSmod,      BVShl,
              BVAshr,      BVLshr,      BVUlt,  BVUle,       BVUgt,
              BVUge,       BVSlt,       BVSle,  BVSgt,       BVSge,
              Zero_Extend, Sign_Extend, Repeat, Rotate_Left, Rotate_Right };
      break;
    case LogicTheory::BVIA:
      if (!strict_)
      {
        ops = { Int_To_BV, UBV_To_Int, SBV_To_Int };
        // obsolete spellings of int_to_bv and ubv_to_int
        primops_.emplace("int2bv", Int_To_BV);
        primops_.emplace("bv2nat", UBV_To_Int);
      }
      break;
    case LogicTheory::S:
      sort = STRING;
      ops = { StrLt,       StrLeq,      StrLen,     StrConcat,  StrSubstr,
              StrAt,       StrContains, StrIndexof, StrReplace, StrReplaceAll,
              StrPrefixof, StrSuffixof, StrIsDigit };
      break;
    case LogicTheory::A:
      sort = ARRAY;
      ops = { Select, Store };
      break;
    case LogicTheory::NUM_THEORIES: break;
  }

  if (sort)
  {
    sortkinds_.emplace(to_string(*sort), *sort);
  }
  for (const PrimOp po : ops)
  {
    primops_.emplace(to_string(po), po);
  }
}

void SmtLibReader::set_opt(const std::string & key, const std::string & val)
{
  solver_->set_opt(key, val);
}

void SmtLibReader::set_info(const std::string & /* key */,
                            const std::string & /* val */)
{
  // No-Op for set-info by default
}

void SmtLibReader::declare_fun(const std::string & name,
                               SortVec domain,
                               const Sort & sort)
{
  if (domain.empty())
  {
    new_symbol(name, sort);
    return;
  }
  domain.push_back(sort);
  new_symbol(name, solver_->make_sort(FUNCTION, domain));
}

void SmtLibReader::declare_sort(const std::string & name, std::uint64_t arity)
{
  SmtLibReader::define_sort(name, solver_->make_sort(name, arity));
}

void SmtLibReader::assert_formula(const Term & assertion)
{
  solver_->assert_formula(assertion);
}

Result SmtLibReader::check_sat()
{
  Result r = solver_->check_sat();
  std::cout << r << std::endl;
  return r;
}

Result SmtLibReader::check_sat_assuming(const TermVec & assumptions)
{
  Result r = solver_->check_sat_assuming(assumptions);
  std::cout << r << std::endl;
  return r;
}

void SmtLibReader::get_value(const TermVec & terms)
{
  std::cout << "(";
  for (const auto & t : terms)
  {
    std::cout << "(" << t << " " << solver_->get_value(t) << ") " << std::endl;
  }
  std::cout << ")" << std::endl;
}

void SmtLibReader::get_unsat_assumptions()
{
  UnorderedTermSet core;
  solver_->get_unsat_assumptions(core);
  std::cout << "(";
  for (const auto & c : core)
  {
    std::cout << c << std::endl;
  }
  std::cout << ")" << std::endl;
}

void SmtLibReader::push(std::uint64_t num)
{
  for (std::size_t i = 0; i < num; ++i)
  {
    global_symbols_.push_scope();
  }
  solver_->push(num);
}

void SmtLibReader::pop(std::uint64_t num)
{
  for (std::size_t i = 0; i < num; ++i)
  {
    global_symbols_.pop_scope();
  }
  solver_->pop(num);
}

void SmtLibReader::echo(const std::string & text)
{
  std::cout << text << std::endl;
}

void SmtLibReader::term_attribute(const Term & /* term */,
                                  const std::string & keyword,
                                  const std::string & value)
{
  std::cerr << "Warning: ignoring attribute :" << keyword << " " << value
            << std::endl;
}

const SmtSolver & SmtLibReader::solver() const { return solver_; }

bool SmtLibReader::is_strict() const { return strict_; }

void SmtLibReader::push_scope()
{
  arg_param_map_.push_scope();
  sort_arg_ids_.push_back(std::unordered_map<Sort, std::size_t>());
}

void SmtLibReader::pop_scope()
{
  arg_param_map_.pop_scope();
  sort_arg_ids_.pop_back();
}

std::size_t SmtLibReader::current_scope() const
{
  return arg_param_map_.current_scope();
}

Term SmtLibReader::lookup_symbol(const std::string & sym) const
{
  Term symbol_term;

  if (sym == "true")
  {
    return solver_->make_term(true);
  }
  else if (sym == "false")
  {
    return solver_->make_term(false);
  }

  if (current_scope())
  {
    // check scoped variables before global symbols
    // shadowing semantics
    symbol_term = arg_param_map_.get_symbol(sym);
    if (symbol_term)
    {
      return symbol_term;
    }
  }

  symbol_term = global_symbols_.get_symbol(sym);
  return symbol_term;
}

void SmtLibReader::new_symbol(const std::string & name, const Sort & sort)
{
  if (global_symbols_.get_symbol(name))
  {
    throw IncorrectUsageException("Redeclaring symbol: " + name);
  }

  auto it = all_symbols_.find(name);
  if (it != all_symbols_.end())
  {
    if (it->second->get_sort() != sort)
    {
      throw NotImplementedException(
          "Current Limitation: cannot redeclare symbol " + name
          + " with a different sort");
    }
    global_symbols_.add_mapping(name, it->second);
    return;
  }

  if (strict_ && !allow_ufs_ && sort->get_sort_kind() == FUNCTION)
  {
    throw IncorrectUsageException("Tried to declare UF, but current logic "
                                  + logic_ + " does not support UFs");
  }

  Term fresh_symbol = solver_->make_symbol(name, sort);
  global_symbols_.add_mapping(name, fresh_symbol);
  all_symbols_[name] = fresh_symbol;
}

PrimOp SmtLibReader::lookup_primop(const std::string & str) const
{
  auto it = primops_.find(str);
  if (it != primops_.end())
  {
    return it->second;
  }
  else
  {
    // returning null because not in set of operators
    // (at least for the logic that was set)
    return NUM_OPS_AND_NULL;
  }
}

Term SmtLibReader::apply_primop(PrimOp po, TermVec args) const
{
  if (po == Minus && args.size() == 1)
  {
    return solver_->make_term(Negate, args[0]);
  }

  // SMT-LIB declares the arithmetic operators as (op Real Real s), for which
  // the logic AUFLIRA makes an Int argument next to a Real one, and every Int
  // argument of /, syntactic sugar for its conversion with to_real.
  if (lookup_sortkind(to_string(INT)) == INT
      && lookup_sortkind(to_string(REAL)) == REAL
      && (get_theory(po) == Theory::ARITH || get_theory(po) == Theory::REALS
          || (!strict_ && (po == Equal || po == Distinct)))
      && (po == Div
          || std::any_of(args.begin(), args.end(), has_sort_kind(REAL))))
  {
    for (Term & arg : args)
    {
      if (has_sort_kind(INT, arg))
      {
        arg = solver_->make_term(To_Real, arg);
      }
    }
  }
  return solver_->make_term(po, args);
}

Term SmtLibReader::apply_symbol(const std::string & name, TermVec args)
{
  PrimOp po = lookup_primop(name);
  if (po != NUM_OPS_AND_NULL)
  {
    return apply_primop(po, std::move(args));
  }
  Term uf = lookup_symbol(name);
  if (uf)
  {
    args.insert(args.begin(), uf);
    return solver_->make_term(Apply, args);
  }
  return apply_define_fun(name, args);
}

SortKind SmtLibReader::lookup_sortkind(const std::string & str) const
{
  SortKind sk = NUM_SORT_KINDS;
  auto it = sortkinds_.find(str);
  if (it != sortkinds_.end())
  {
    sk = it->second;
  }
  return sk;
}

void SmtLibReader::define_fun(const std::string & name,
                              const Term & def,
                              const TermVec & args)
{
  if (args.size())
  {
    // this is a function
    defs_[name] = def;
    def_args_[name] = args;
  }
  else
  {
    // this is just an alias for another term
    if (global_symbols_.get_symbol(name))
    {
      throw IncorrectUsageException("Redeclaring symbol: " + name);
    }
    global_symbols_.add_mapping(name, def);
  }
}

Term SmtLibReader::apply_define_fun(const std::string & defname,
                                    const TermVec & args)
{
  UnorderedTermMap subs_map;
  std::size_t num_args = args.size();

  auto it = defs_.find(defname);

  if (it == defs_.end())
  {
    throw IncorrectUsageException("Unknown function: " + defname);
  }

  Term def = it->second;

  if (num_args != def_args_.at(defname).size())
  {
    throw IncorrectUsageException(
        defname + " not applied to correct number of arguments.");
  }

  for (std::size_t i = 0; i < args.size(); ++i)
  {
    subs_map[def_args_.at(defname)[i]] = args[i];
  }

  return solver_->substitute(def, subs_map);
}

Term SmtLibReader::register_arg(const std::string & name, const Sort & sort)
{
  if (!current_scope())
  {
    throw IncorrectUsageException("register_arg needs a scope from push_scope");
  }
  // find the right id for this argument
  // can't associate with same variable as another argument for this define-fun
  std::size_t id = 0;
  std::unordered_map<Sort, std::size_t> & current_scope_sort_ids =
      sort_arg_ids_.back();
  auto it = current_scope_sort_ids.find(sort);
  if (it != current_scope_sort_ids.end())
  {
    id = it->second;
  }
  else
  {
    current_scope_sort_ids[sort] = 0;
  }

  Term tmpvar;
  if (id >= tmp_args_[sort].size())
  {
    tmpvar = solver_->make_symbol(
        def_arg_prefix_ + sort->to_string() + std::to_string(id), sort);
    tmp_args_[sort].push_back(tmpvar);
  }
  else
  {
    tmpvar = tmp_args_[sort].at(id);
  }

  arg_param_map_.add_mapping(name, tmpvar);
  current_scope_sort_ids[sort]++;
  return tmpvar;
}

void SmtLibReader::define_sort(const std::string & name, const Sort & sort)
{
  if (sortkinds_.find(name) != sortkinds_.end())
  {
    throw IncorrectUsageException("Cannot define sort " + name + " in logic "
                                  + logic_);
  }
  else if (defined_sorts_.find(name) != defined_sorts_.end())
  {
    throw IncorrectUsageException("Cannot re-define sort with name " + name);
  }
  defined_sorts_[name] = sort;
}

Sort SmtLibReader::lookup_sort(const std::string & name) const
{
  auto it = defined_sorts_.find(name);
  if (it == defined_sorts_.end())
  {
    throw IncorrectUsageException("Unknown defined sort symbol " + name);
  }
  return it->second;
}

Sort SmtLibReader::make_sort(const std::string & name) const
{
  SortKind sk = lookup_sortkind(name);
  if (sk == NUM_SORT_KINDS || sk == UNINTERPRETED)
  {
    return lookup_sort(name);
  }
  return solver_->make_sort(sk);
}

Sort SmtLibReader::make_sort(const std::string & name,
                             std::uint64_t index) const
{
  SortKind sk = lookup_sortkind(name);
  if (sk == NUM_SORT_KINDS)
  {
    return Sort();
  }
  return solver_->make_sort(sk, index);
}

Sort SmtLibReader::make_sort(const std::string & name,
                             const SortVec & sorts) const
{
  if (lookup_sortkind(name) == ARRAY)
  {
    if (sorts.size() != 2)
    {
      return Sort();
    }
    return solver_->make_sort(ARRAY, sorts[0], sorts[1]);
  }
  return solver_->make_sort(lookup_sort(name), sorts);
}

Term SmtLibReader::make_bv_literal(const std::string & name,
                                   std::uint64_t width) const
{
  if (name.size() < 3 || name.compare(0, 2, "bv") != 0
      || name.find_first_not_of("0123456789", 2) != std::string::npos)
  {
    return Term();
  }
  return solver_->make_term(name.substr(2), solver_->make_sort(BV, width), 10);
}

Term SmtLibReader::make_bv_value(const std::string & digits,
                                 std::uint64_t base) const
{
  std::uint64_t width = digits.size() * (base == 16 ? 4 : 1);
  return solver_->make_term(digits, solver_->make_sort(BV, width), base);
}

Term SmtLibReader::make_numeral(const std::string & n) const
{
  SortKind sk = lookup_sortkind(to_string(INT)) == NUM_SORT_KINDS
                        && lookup_sortkind(to_string(REAL)) == REAL
                    ? REAL
                    : INT;
  return solver_->make_term(n, solver_->make_sort(sk));
}

Term SmtLibReader::create_param(const std::string & name, const Sort & sort)
{
  if (!current_scope())
  {
    throw IncorrectUsageException("create_param needs a scope from push_scope");
  }
  Term param;
  // some solvers don't allow reusing parameter names
  // need to find a fresh one
  std::size_t id = 0;
  while (!param)
  {
    try
    {
      param = solver_->make_param(name + "__param_" + std::to_string(id), sort);
    }
    // a name already taken is what a fresh one cures; if none does, the
    // solver's own reason is reported
    catch (const IncorrectUsageException &)
    {
      if (++id > 100000)
      {
        throw;
      }
    }
  }
  arg_param_map_.add_mapping(name, param);
  return param;
}

void SmtLibReader::let_binding(const std::string & sym, const Term & term)
{
  if (!current_scope())
  {
    throw IncorrectUsageException("let_binding needs a scope from push_scope");
  }
  arg_param_map_.add_mapping(sym, term);
}

}  // namespace smt
